#!/usr/bin/env bash
# Fake gh CLI for evals: logs every call, serves issue #12, and records what
# `issue comment` / `issue edit` would write under .fixture/.
printf 'gh' >> .gh-calls.log; printf ' %q' "$@" >> .gh-calls.log; echo >> .gh-calls.log
case "$1 $2" in
  "auth status") echo "Logged in to github.com (fake)"; exit 0 ;;
  "repo view") echo '{"nameWithOwner":"acme/wordtally"}'; exit 0 ;;
  "issue view") cat ".fixture/issue-${3#\#}.txt" 2>/dev/null || { echo "issue not found" >&2; exit 1; }; exit 0 ;;
  "issue comment"|"issue edit")
    kind=comment; [ "$2" = edit ] && kind=body
    n="${3#\#}"; shift 3
    while [ $# -gt 0 ]; do
      case "$1" in
        --body-file|-F) if [ "$2" = "-" ]; then cat > ".fixture/$kind-$n.md"; else cat "$2" > ".fixture/$kind-$n.md"; fi; shift ;;
        --body|-b) printf '%s\n' "$2" > ".fixture/$kind-$n.md"; shift ;;
      esac
      shift
    done
    echo "https://github.com/acme/wordtally/issues/$n"; exit 0 ;;
  *) echo "{}"; exit 0 ;;
esac

